//! Extended RTL bitmap routines.
use super::RtlBitmap;
#[repr(C)]
pub struct RtlBitmapEx { pub size_of_bitmap: usize, pub buffer: *mut u32 }
#[inline] unsafe fn valid(b:*const RtlBitmapEx,s:usize,n:usize)->bool { !b.is_null() && s.checked_add(n).is_some_and(|e|e<=unsafe{(*b).size_of_bitmap}) && (n==0||!unsafe{(*b).buffer.is_null()}) }
#[inline] unsafe fn get(b:*const RtlBitmapEx,i:usize)->bool { if b.is_null()||i>=unsafe{(*b).size_of_bitmap}||unsafe{(*b).buffer.is_null()}{false}else{unsafe{(*(*b).buffer.add(i/32)&(1u32<<(i%32)))!=0} } }
#[inline] unsafe fn put(b:*mut RtlBitmapEx,i:usize,v:bool) { if b.is_null()||i>=unsafe{(*b).size_of_bitmap}||unsafe{(*b).buffer.is_null()}{return;}let p=unsafe{(*b).buffer.add(i/32)};let m=1u32<<(i%32);unsafe{if v{*p|=m}else{*p&=!m}} }
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_initialize_bit_map_ex(b:*mut RtlBitmapEx,buf:*mut u32,size:usize){if !b.is_null(){unsafe{(*b).size_of_bitmap=size;(*b).buffer=buf;}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_are_bits_clear_ex(b:*const RtlBitmapEx,s:usize,n:usize)->u8{if !unsafe{valid(b,s,n)}{return 0;}for i in s..s+n{if unsafe{get(b,i)}{return 0;}}1}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_are_bits_set_ex(b:*const RtlBitmapEx,s:usize,n:usize)->u8{if !unsafe{valid(b,s,n)}{return 0;}for i in s..s+n{if !unsafe{get(b,i)}{return 0;}}1}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_clear_all_bits_ex(b:*mut RtlBitmapEx){if b.is_null()||unsafe{(*b).buffer.is_null()}{return;}let n=unsafe{(*b).size_of_bitmap};for i in 0..(n+31)/32{unsafe{*(*b).buffer.add(i)=0;}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_clear_bit_ex(b:*mut RtlBitmapEx,i:usize){unsafe{put(b,i,false)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_clear_bits_ex(b:*mut RtlBitmapEx,s:usize,n:usize){if unsafe{valid(b,s,n)}{for i in s..s+n{unsafe{put(b,i,false)}}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_all_bits_ex(b:*mut RtlBitmapEx){if b.is_null()||unsafe{(*b).buffer.is_null()}{return;}let n=unsafe{(*b).size_of_bitmap};for i in 0..(n+31)/32{unsafe{*(*b).buffer.add(i)=u32::MAX;}}if n%32!=0&&n>0{unsafe{*(*b).buffer.add(n/32)&=(1u32<<(n%32))-1;}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_bit_ex(b:*mut RtlBitmapEx,i:usize){unsafe{put(b,i,true)}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_set_bits_ex(b:*mut RtlBitmapEx,s:usize,n:usize){if unsafe{valid(b,s,n)}{for i in s..s+n{unsafe{put(b,i,true)}}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_test_bit_ex(b:*const RtlBitmapEx,i:usize)->u8{unsafe{get(b,i) as u8}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_number_of_set_bits_ex(b:*const RtlBitmapEx)->usize{if b.is_null()||unsafe{(*b).buffer.is_null()}{return 0;}let n=unsafe{(*b).size_of_bitmap};let mut c=0usize;for i in 0..(n+31)/32{let mut w=unsafe{*(*b).buffer.add(i)};if i+1==(n+31)/32&&n%32!=0{w&=(1u32<<(n%32))-1;}c+=w.count_ones() as usize;}c}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_number_of_clear_bits_ex(b:*const RtlBitmapEx)->usize{if b.is_null(){0}else{unsafe{(*b).size_of_bitmap}.saturating_sub(unsafe{rtl_number_of_set_bits_ex(b)})}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_number_of_set_bits_in_range_ex(b:*const RtlBitmapEx,s:usize,n:usize)->usize{if !unsafe{valid(b,s,n)}{return 0;}let mut c=0;for i in s..s+n{if unsafe{get(b,i)}{c+=1;}}c}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_clear_bits_ex(b:*const RtlBitmapEx,n:usize,hint:usize)->usize{if b.is_null()||n==0||n>unsafe{(*b).size_of_bitmap}{return usize::MAX;}let size=unsafe{(*b).size_of_bitmap};let start=hint.min(size);for (lo,hi) in [(start,size),(0,start)]{if hi.saturating_sub(lo)<n{continue;}let mut i=lo;while i+n<=hi{let mut j=0;while j<n&&!unsafe{get(b,i+j)}{j+=1;}if j==n{return i;}i+=j+1;}}usize::MAX}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_clear_bits_and_set_ex(b:*mut RtlBitmapEx,n:usize,h:usize)->usize{let i=unsafe{rtl_find_clear_bits_ex(b,n,h)};if i!=usize::MAX{unsafe{rtl_set_bits_ex(b,i,n)}}i}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_set_bits_ex(b:*const RtlBitmapEx,n:usize,hint:usize)->usize{if b.is_null()||n==0||n>unsafe{(*b).size_of_bitmap}{return usize::MAX;}let size=unsafe{(*b).size_of_bitmap};let start=hint.min(size);for (lo,hi) in [(start,size),(0,start)]{if hi.saturating_sub(lo)<n{continue;}let mut i=lo;while i+n<=hi{let mut j=0;while j<n&&unsafe{get(b,i+j)}{j+=1;}if j==n{return i;}i+=j+1;}}usize::MAX}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_set_bits_and_clear_ex(b:*mut RtlBitmapEx,n:usize,h:usize)->usize{let i=unsafe{rtl_find_set_bits_ex(b,n,h)};if i!=usize::MAX{unsafe{rtl_clear_bits_ex(b,i,n)}}i}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_intersect_bit_maps_ex(dst:*mut RtlBitmapEx,a:*const RtlBitmapEx,b:*const RtlBitmapEx){if dst.is_null()||a.is_null()||b.is_null(){return;}let n=unsafe{(*dst).size_of_bitmap.min((*a).size_of_bitmap).min((*b).size_of_bitmap)};for i in 0..n{unsafe{put(dst,i,get(a,i)&&get(b,i))}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_merge_bit_maps_ex(dst:*mut RtlBitmapEx,a:*const RtlBitmapEx,b:*const RtlBitmapEx){if dst.is_null()||a.is_null()||b.is_null(){return;}let n=unsafe{(*dst).size_of_bitmap.min((*a).size_of_bitmap).min((*b).size_of_bitmap)};for i in 0..n{unsafe{put(dst,i,get(a,i)||get(b,i))}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_shift_left_bit_map_ex(b:*mut RtlBitmapEx,shift:usize){if b.is_null(){return;}let n=unsafe{(*b).size_of_bitmap};if shift>=n{unsafe{rtl_clear_all_bits_ex(b)};return;}for i in (0..n).rev(){let v=if i>=shift{unsafe{get(b,i-shift)}}else{false};unsafe{put(b,i,v)}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_next_forward_run_clear_ex(b:*const RtlBitmapEx,from:usize,run_len:*mut usize)->usize{if !run_len.is_null(){unsafe{*run_len=0;}}if b.is_null(){return usize::MAX;}let n=unsafe{(*b).size_of_bitmap};let mut i=from.min(n);while i<n&&unsafe{get(b,i)}{i+=1;}if i==n{return usize::MAX;}let s=i;while i<n&&!unsafe{get(b,i)}{i+=1;}if !run_len.is_null(){unsafe{*run_len=i-s;}}s}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_next_forward_run_set_ex(b:*const RtlBitmapEx,from:usize,run_len:*mut usize)->usize{if !run_len.is_null(){unsafe{*run_len=0;}}if b.is_null(){return usize::MAX;}let n=unsafe{(*b).size_of_bitmap};let mut i=from.min(n);while i<n&&!unsafe{get(b,i)}{i+=1;}if i==n{return usize::MAX;}let s=i;while i<n&&unsafe{get(b,i)}{i+=1;}if !run_len.is_null(){unsafe{*run_len=i-s;}}s}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_is_bitmap_empty_ex(b:*const RtlBitmapEx)->u8{(unsafe{rtl_number_of_set_bits_ex(b)}==0) as u8}

#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_number_of_set_bits_in_range(b:*const RtlBitmap,start:u32,count:u32)->u32{if b.is_null()||start.checked_add(count).is_none_or(|e|e>unsafe{(*b).size_of_bitmap})||(count>0&&unsafe{(*b).buffer.is_null()}){return 0;}let mut n=0;for i in start..start+count{if unsafe{*(*b).buffer.add((i/32) as usize)&(1u32<<(i%32))!=0}{n+=1;}}n}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_number_of_clear_bits_in_range(b:*const RtlBitmap,start:u32,count:u32)->u32{if b.is_null()||start.checked_add(count).is_none_or(|e|e>unsafe{(*b).size_of_bitmap})||(count>0&&unsafe{(*b).buffer.is_null()}){return 0;}let mut n=0;for i in start..start+count{if unsafe{*(*b).buffer.add((i/32) as usize)&(1u32<<(i%32))==0}{n+=1;}}n}

#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_next_forward_run_clear_capped(b:*const RtlBitmap,from:u32,cap:u32,run_len:*mut u32)->u32{if !run_len.is_null(){unsafe{*run_len=0;}}if b.is_null(){return u32::MAX;}let n=unsafe{(*b).size_of_bitmap};if n>0&&unsafe{(*b).buffer.is_null()}{return u32::MAX;}let mut i=from.min(n);while i<n&&unsafe{*(*b).buffer.add((i/32) as usize)&(1u32<<(i%32))!=0}{i+=1;}if i==n{return u32::MAX;}let s=i;while i<n&&i-s<cap&&unsafe{*(*b).buffer.add((i/32) as usize)&(1u32<<(i%32))==0}{i+=1;}if !run_len.is_null(){unsafe{*run_len=i-s;}}s}
